sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float fadeIn;
uniform float fadeOut;
uniform float duration;
half4 main(float2 coord) {
    float a = 1.0;
    if (fadeIn > 0.0) a *= clamp(time / fadeIn, 0.0, 1.0);
    if (fadeOut > 0.0) a *= clamp((duration - time) / fadeOut, 0.0, 1.0);
    return image.eval(coord) * half(a);
}
